style.css:
/* Dark theme like ChatGPT */
* {
    background-color: #202123 !important;
    color: #d1d5db !important;
    border-color: #2d2f34 !important;
}

/* Links */
a {
    color: #4aa3ff !important;
}
a:hover {
    color: #86c1ff !important;
}

/* Buttons */
button, input[type="submit"], input[type="button"] {
    background-color: #2d2f34 !important;
    color: #d1d5db !important;
    border: 1px solid #3b3f44 !important;
}
button:hover, input[type="submit"]:hover, input[type="button"]:hover {
    background-color: #3b3f44 !important;
}

/* Inputs & Textareas */
input, textarea, select {
    background-color: #2d2f34 !important;
    color: #d1d5db !important;
    border: 1px solid #3b3f44 !important;
}

/* Tables */
table {
    background-color: #202123 !important;
}
th, td {
    border-color: #3b3f44 !important;
}

/* Remove bright box shadows */
*:focus {
    outline: none !important;
    box-shadow: 0 0 4px #4aa3ff !important;
}
